using System;using System.Collections.Generic;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Media.Media3D;
namespace DragonCompanion {
// GPU textured mesh: animate the rendered sprite only. Never edits source images or Codex.
// All six forms share one light rig so silver-white materials keep the same color family.
public sealed class AnimatedPortrait:Grid {
 readonly Viewport3D viewport=new Viewport3D();readonly MeshGeometry3D mesh=new MeshGeometry3D();readonly OrthographicCamera camera=new OrthographicCamera();readonly Aura aura;readonly Stars stars;readonly Stopwatch clock=Stopwatch.StartNew();readonly List<Point> rest=new List<Point>();BitmapImage source;string kind="full";double aspect=1,lastFrame=-1;bool attached;double switchedAt=-100,reactedAt=-100;int reaction;public bool EconomyMode;readonly DirectionalLight keyLight=new DirectionalLight(Colors.White,new Vector3D(-.3,-.4,-1));readonly AmbientLight fillLight=new AmbientLight(Color.FromRgb(165,165,180));
 public int Tier{get{return kind=="chibi"?0:kind=="medium"?1:kind=="full"?2:kind=="xhigh"?3:kind=="max"?4:5;}}
 double Gain{get{return 4.2+Tier*.82;}}
 public AnimatedPortrait(){ClipToBounds=false;IsHitTestVisible=false;aura=new Aura(this);Children.Add(aura);viewport.Camera=camera;RenderOptions.SetEdgeMode(viewport,EdgeMode.Aliased);Children.Add(viewport);stars=new Stars(this);Children.Add(stars);var model=new GeometryModel3D{Geometry=mesh};var visual=new ModelVisual3D{Content=model};viewport.Children.Add(visual);viewport.Children.Add(new ModelVisual3D{Content=fillLight});viewport.Children.Add(new ModelVisual3D{Content=keyLight});Model=model;Loaded+=(s,e)=>Attach();Unloaded+=(s,e)=>Detach();IsVisibleChanged+=(s,e)=>{if(IsVisible)Attach();else Detach();};SizeChanged+=(s,e)=>{LayoutCamera();aura.InvalidateVisual();};}
 GeometryModel3D Model;
 static BitmapSource UploadTexture(BitmapSource input){var straight=new FormatConvertedBitmap(input,PixelFormats.Bgra32,null,0);int stride=straight.PixelWidth*4;var bytes=new byte[stride*straight.PixelHeight];straight.CopyPixels(bytes,stride,0);for(int i=0;i<bytes.Length;i+=4){int a=bytes[i+3];if(a>240)a=255;bytes[i+3]=(byte)a;for(int c=0;c<3;c++)bytes[i+c]=(byte)((bytes[i+c]*a+127)/255);}var output=BitmapSource.Create(straight.PixelWidth,straight.PixelHeight,96,96,PixelFormats.Pbgra32,null,bytes,stride);output.Freeze();return output;}
 public BitmapImage Source {get{return source;}set{if(source==value)return;source=value;aspect=(double)value.PixelWidth/value.PixelHeight;var brush=new ImageBrush(UploadTexture(value)){Stretch=Stretch.Fill};brush.Freeze();var material=new DiffuseMaterial(brush);material.Freeze();Model.Material=material;Model.BackMaterial=material;BuildMesh();LayoutCamera();Step(clock.Elapsed.TotalSeconds);}}
 public string Form {get{return kind;}set{kind=value;switchedAt=clock.Elapsed.TotalSeconds;BuildMesh();LayoutCamera();Step(clock.Elapsed.TotalSeconds);}}
 public bool MotionEnabled=true;
 public void React(){double now=clock.Elapsed.TotalSeconds;if(now-reactedAt<.22)return;reaction=(reaction+1)%3;reactedAt=now;}
 public static double ReplyEnvelope(double age){return age>=0&&age<1.3?Math.Sin(Math.PI*age/1.3)*Math.Exp(-age*.5):0;}
 internal double Reply(double t){return ReplyEnvelope(t-reactedAt);}

 void Attach(){if(attached)return;CompositionTarget.Rendering+=OnFrame;attached=true;}
 void Detach(){if(!attached)return;CompositionTarget.Rendering-=OnFrame;attached=false;}
 void OnFrame(object sender,EventArgs e){if(!MotionEnabled||!IsVisible||Opacity<=0||Window.GetWindow(this)==null||Window.GetWindow(this).Opacity<=0)return;double t=clock.Elapsed.TotalSeconds;if(t-lastFrame<1.0/(EconomyMode?20:30))return;lastFrame=t;Step(t);}
 static void AddAround(SortedSet<double> set,double center,double radius,int count){for(int i=-count;i<=count;i++){double p=center+radius*i/count;if(p>0&&p<1)set.Add(p);}}
 void BuildMesh(){if(source==null)return;rest.Clear();var xs=new SortedSet<double>();var ys=new SortedSet<double>();for(int i=0;i<=32;i++)xs.Add(i/32.0);for(int i=0;i<=48;i++)ys.Add(i/48.0);Point[] eyes=kind=="chibi"?Eyes():new Point[0];foreach(var eye in eyes){AddAround(xs,eye.X,kind=="chibi"?.046:.025,3);AddAround(ys,eye.Y,kind=="chibi"?.023:.009,4);}var x=Separated(xs);var y=Separated(ys);var uv=new PointCollection();var indices=new Int32Collection();for(int j=0;j<y.Count;j++)for(int i=0;i<x.Count;i++){var p=new Point(x[i],y[j]);rest.Add(p);uv.Add(p);if(i<x.Count-1&&j<y.Count-1){int a=j*x.Count+i,b=a+1,c=a+x.Count,d=c+1;indices.Add(a);indices.Add(c);indices.Add(b);indices.Add(b);indices.Add(c);indices.Add(d);}}uv.Freeze();indices.Freeze();mesh.TextureCoordinates=uv;mesh.TriangleIndices=indices;}
 static List<double> Separated(SortedSet<double> values){var result=new List<double>();foreach(double v in values){if(result.Count==0||v-result[result.Count-1]>.002)result.Add(v);}return result;}
 Point[] Eyes(){if(kind=="chibi")return new[]{new Point(.449,.364),new Point(.574,.323)};if(kind=="ultra")return new[]{new Point(.482,.211),new Point(.550,.204)};return new[]{new Point(.465,.155),new Point(.550,.144)};}
 static double G(double u,double v,double x,double y,double rx,double ry){double dx=(u-x)/rx,dy=(v-y)/ry;return Math.Exp(-2.2*(dx*dx+dy*dy));}
 public static double Blink(double t){double phase=t%5.7;if(phase<3.20||phase>3.48)return 0;double p=(phase-3.20)/.28;return Math.Pow(Math.Sin(p*Math.PI),1.3);}
 public void Step(double t){if(rest.Count==0)return;var points=new Point3DCollection(rest.Count);double age=Math.Max(0,clock.Elapsed.TotalSeconds-switchedAt);double burst=age<.85?Math.Sin(age/.85*Math.PI)*(.13+Tier*.012):0;keyLight.Direction=new Vector3D(Math.Sin(t*.75)*.8,-.4,-1);fillLight.Color=Color.FromRgb(165,165,180);keyLight.Color=Color.FromRgb((byte)(180+60*(.5+.5*Math.Sin(t*.9))),(byte)(160+60*(.5+.5*Math.Sin(t*.9))),255);double blink=Blink(t),breath=Math.Sin(t*1.65),wing=Math.Sin(t*(kind=="ultra"?1.7:1.15)),hair=Math.Sin(t*.85);Point[] eyes=kind=="chibi"?Eyes():new Point[0];foreach(var p in rest){double u=p.X,v=p.Y,x=u,y=v;double body=G(u,v,.5,.52,.28,.32);y-=.0028*breath*body;x+=(u-.5)*.006*breath*body;
  if(kind=="chibi"){
   x+=.012*Math.Sin(t*1.2+v*4)*G(u,v,.83,.76,.2,.26); // tail sway
   double head=G(u,v,.50,.24,.46,.37),angle=.012*Math.Sin(t*.63);x+=-(v-.30)*angle*head;y+=(u-.5)*angle*head;
  }else{
   double sides=Math.Min(1,Math.Abs(u-.5)*3.2);x+=.006*Math.Sin(t*.95+v*5.4)*G(u,v,.5,.48,.55,.4)*sides; // hair drift
   x+=.005*Math.Sin(t*.90+u*7)*G(u,v,.5,.83,.45,.25);y+=.0025*Math.Sin(t*.8+u*7)*G(u,v,.5,.88,.45,.2); // dress
   double wleft=G(u,v,.16,kind=="ultra"?.36:.25,.23,kind=="ultra"?.38:.17),wright=G(u,v,.85,kind=="ultra"?.36:.25,.22,kind=="ultra"?.38:.17);
   x+=.009*wing*(wright-wleft);y+=.005*Math.Sin(t*1.15+.4)*(wleft+wright); // wing flex
   x+=.005*Math.Sin(t*.85+v*5)*G(u,v,.87,.72,.15,.25); // tail
   if(kind=="ultra"){y-=.009*(1+Math.Sin(t*1.25));x+=.004*Math.Sin(t*.8);} // levitation
  }
  x=u+(x-u)*Gain;y=v+(y-v)*Gain;foreach(var eye in eyes){double rw=kind=="chibi"?.047:.025,rh=kind=="chibi"?.023:.010;double g=Math.Exp(-1.4*(Math.Pow((u-eye.X)/rw,6)+Math.Pow((v-eye.Y)/rh,6)));y+=(eye.Y-v)*.985*blink*g;} double response=Reply(t);double tilt=(reaction==0?.085:reaction==1?-.07:.04)*response*Math.Sin((t-reactedAt)*9);double dx=x-.5,dy=y-.53;x=.5+dx*Math.Cos(tilt)-dy*Math.Sin(tilt);y=.53+dx*Math.Sin(tilt)+dy*Math.Cos(tilt)-response*(reaction==2?.065:.038);x+=(u-.5)*response*.035;double zoom=1+burst+response*.035;x=.5+(x-.5)*zoom;y=.52+(y-.52)*zoom;double z=kind=="chibi"?0:.07*Math.Sin(t*1.15)*Math.Min(1,Math.Abs(u-.5)*3.5)*G(u,v,.5,.35,.7,.35);points.Add(new Point3D((x-.5)*aspect,.5-y,z));}
 points.Freeze();mesh.Positions=points;aura.Time=t;aura.InvalidateVisual();stars.Time=t;stars.InvalidateVisual();}
 void LayoutCamera(){if(ActualWidth<=0||ActualHeight<=0)return;double w=Math.Max(aspect,ActualWidth/ActualHeight)*1.30;camera.Width=w;double vh=w*ActualHeight/ActualWidth;camera.Position=new Point3D(0,-.5+vh/2,10);camera.LookDirection=new Vector3D(0,0,-1);camera.UpDirection=new Vector3D(0,1,0);}
 internal Rect SpriteRect(){if(ActualWidth<=0||ActualHeight<=0)return Rect.Empty;double unit=ActualWidth/camera.Width;return new Rect(ActualWidth/2-aspect*unit/2,ActualHeight-unit,aspect*unit,unit);}
 sealed class Stars:FrameworkElement {
 readonly AnimatedPortrait owner;public double Time;readonly Brush white=new SolidColorBrush(Color.FromArgb(245,255,248,255));readonly Brush violet=new SolidColorBrush(Color.FromArgb(210,199,148,255));
 public Stars(AnimatedPortrait p){owner=p;IsHitTestVisible=false;white.Freeze();violet.Freeze();}
 static StreamGeometry Star(double x,double y,double radius,double angle){var g=new StreamGeometry();using(var c=g.Open()){for(int j=0;j<8;j++){double a=angle+j*Math.PI/4,rr=j%2==0?radius:radius*.23;var p=new Point(x+Math.Cos(a)*rr,y+Math.Sin(a)*rr);if(j==0)c.BeginFigure(p,true,true);else c.LineTo(p,true,false);}}g.Freeze();return g;}
 protected override void OnRender(DrawingContext dc){Rect r=owner.SpriteRect();if(r.IsEmpty)return;int tier=owner.Tier;double t=Time;bool ultra=tier==5;int count=10+tier*5+(ultra?25:0);if(owner.EconomyMode)count=(count+1)/2;
  for(int i=0;i<count;i++){double phase=(i*.61803398875+t*(.11+tier*.012))%1;double angle=i*2.399963+t*(i%2==0?.32:-.24);double spread=.33+.15*Math.Sin(i*1.71);double x=r.X+r.Width*(.5+Math.Cos(angle)*spread),y=r.Y+r.Height*(.94-phase*.91);if(ultra){double side=i%2==0?-1:1;x=r.X+r.Width*(.5+side*(.27+.19*(.5+.5*Math.Sin(angle))));}double pulse=Math.Pow(.5+.5*Math.Sin(t*(2+i%3)+i*2.7),2);double alpha=Math.Sin(Math.PI*phase)*(.30+.7*pulse);double radius=(2.5+tier*.6)*(1+pulse*.9);dc.PushOpacity(alpha);dc.DrawEllipse(new RadialGradientBrush(Color.FromArgb(160,188,123,255),Colors.Transparent),null,new Point(x,y),radius*3,radius*3);dc.DrawGeometry(i%3==0?white:violet,null,Star(x,y,radius,t*.35));dc.Pop();}
  double reply=owner.Reply(t);if(reply>0){var center=new Point(r.X+r.Width*.5,r.Y+r.Height*.37);dc.PushOpacity(reply);for(int i=0;i<12;i++){double angle=i*Math.PI/6+t*.8,distance=(1-reply)*r.Width*.6+r.Width*.12;double x=center.X+Math.Cos(angle)*distance,y=center.Y+Math.Sin(angle)*distance*.75;dc.DrawGeometry(white,null,Star(x,y,5+reply*5,t+i));}dc.Pop();}
  if(ultra){var c=new Point(r.X+r.Width*.50,r.Y+r.Height*.83);for(int k=0;k<3;k++){double a=t*(.55+k*.17)+k*Math.PI*2/3;double rx=r.Width*(.48+k*.035),ry=r.Height*(.055+k*.014);var pen=new Pen(new SolidColorBrush(Color.FromArgb((byte)(100+k*25),210,160,255)),1.4+k*.4){DashStyle=new DashStyle(new double[]{8,10},-t*(12+k*7))};dc.PushTransform(new RotateTransform(Math.Sin(t*.45+k)*20,c.X,c.Y));dc.DrawEllipse(null,pen,c,rx,ry);double x=c.X+Math.Cos(a)*rx,y=c.Y+Math.Sin(a)*ry;dc.DrawGeometry(white,null,Star(x,y,9+k*2,t));dc.Pop();}double wave=(t*.55)%1;dc.PushOpacity((1-wave)*.6);dc.DrawEllipse(null,new Pen(violet,2.5),c,r.Width*(.24+wave*.42),r.Height*(.045+wave*.085));dc.Pop();}
 }
 }
 sealed class Aura:FrameworkElement {
 readonly AnimatedPortrait owner;public double Time;readonly Brush[] colors={new SolidColorBrush(Color.FromArgb(190,208,174,255)),new SolidColorBrush(Color.FromArgb(150,241,219,255)),new SolidColorBrush(Color.FromArgb(125,169,145,250))};
 public Aura(AnimatedPortrait owner){this.owner=owner;foreach(var c in colors)c.Freeze();IsHitTestVisible=false;}
 protected override void OnRender(DrawingContext dc){Rect r=owner.SpriteRect();if(r.IsEmpty)return;double t=Time;int tier=owner.Tier;double power=1+tier*.35;dc.PushOpacity(.55+tier*.09);var glow=new RadialGradientBrush(Color.FromArgb((byte)(45+tier*10),155,100,245),Colors.Transparent);dc.DrawEllipse(glow,null,new Point(r.X+r.Width*.5,r.Y+r.Height*.62),r.Width*.58,r.Height*.48);dc.Pop();
  var center=new Point(r.X+r.Width*.51,r.Y+r.Height*(tier==0?.22:.095));double rx=r.Width*(.20+tier*.025),ry=r.Height*.045;
  var pen=new Pen(new SolidColorBrush(Color.FromArgb(105,196,157,245)),2.2);dc.PushTransform(new RotateTransform(Math.Sin(t*.4)*7,center.X,center.Y));dc.DrawEllipse(null,pen,center,rx,ry);var glintPen=new Pen(colors[1],.8){DashStyle=new DashStyle(new double[]{2,8},t*.9)};dc.DrawEllipse(null,glintPen,center,rx*.92,ry*.8);dc.Pop();
  if(tier==5){var c=new Point(r.X+r.Width*.5,r.Y+r.Height*.43);double radius=r.Width*.49;var rim=new Pen(new SolidColorBrush(Color.FromArgb(110,223,196,255)),1.1);dc.PushTransform(new RotateTransform(t*4,c.X,c.Y));for(int i=0;i<12;i++){double a=i*Math.PI/6;var star=new Point(c.X+Math.Cos(a)*radius,c.Y+Math.Sin(a)*radius*.92);var next=new Point(c.X+Math.Cos(a+Math.PI/3)*radius,c.Y+Math.Sin(a+Math.PI/3)*radius*.92);dc.DrawLine(new Pen(new SolidColorBrush(Color.FromArgb(45,194,151,251)),.7),star,next);dc.DrawEllipse(colors[i%3],rim,star,2.5+Math.Sin(t*1.8+i),2.5+Math.Sin(t*1.8+i));}dc.Pop();double age=owner.clock.Elapsed.TotalSeconds-owner.switchedAt;if(age>=0&&age<1.4){double progress=age/1.4;dc.PushOpacity(Math.Sin(progress*Math.PI)*.8);dc.DrawEllipse(null,new Pen(colors[1],2.5*(1-progress)+.5),c,r.Width*(.2+progress*.6),r.Height*(.1+progress*.3));dc.Pop();}}
  // A bounded, deterministic particle field; no background threads and no global overlay.
  for(int i=0;i<(owner.EconomyMode?(18+tier*10)/2:18+tier*10);i++){double phase=(i*.61803398875+t*(.09+tier*.018))%1;double px=r.X+r.Width*(.08+((i*.38196601125)%1)*.84);double py=r.Y+r.Height*(.88-phase*.76);double a=Math.Sin(Math.PI*phase);double radius=(i%3==0?3.0:1.8)*Math.Max(.25,a);var b=colors[i%colors.Length];dc.PushOpacity(a*.95);dc.DrawEllipse(b,null,new Point(px,py),radius,radius);if(i%4==0){dc.DrawLine(new Pen(b,.8),new Point(px-3,py),new Point(px+3,py));dc.DrawLine(new Pen(b,.8),new Point(px,py-3),new Point(px,py+3));}dc.Pop();}
  for(int side=-1;side<=1;side+=2){double sx=r.X+r.Width*.5,ex=r.X+r.Width*(side<0?.13:.88);var geo=new StreamGeometry();using(var g=geo.Open()){g.BeginFigure(new Point(sx,r.Y+r.Height*.92),false,false);g.BezierTo(new Point(sx+side*r.Width*.40,r.Y+r.Height*.80),new Point(ex+side*r.Width*.10,r.Y+r.Height*.39),new Point(ex,r.Y+r.Height*.16),true,false);}geo.Freeze();var flow=new Pen(new SolidColorBrush(Color.FromArgb(85,183,142,241)),2.0){DashStyle=new DashStyle(new double[]{2,16},-t*(8+tier*3))};dc.DrawGeometry(null,flow,geo);}
 }
 }
}
